function queryElement(){var n=getUrlParameter("fundId"),t=getUrlParameter("period");$.ajax({async:!1,url:"/WeixinService/business/queryFundInfo.xhtml",data:{fundId:n,period:t},dataType:"json",type:"post",cache:!1,error:function(){errorRemark("网络繁忙，请稍后再试。")},success:function(n){var i=n.fundInfo;if(typeof i.elementList!="undefined"){var r="",t="";$.each(i.elementList,function(n,i){i.type==210?r+="<li><span>"+i.title+"：<\/span><em>"+i.content+"<\/em><\/li>":i.type==220?t+="<div class='box'><h2><span>"+i.title+"<\/span><\/h2><div class='box-text'><p>"+i.content+"<\/p><\/div><\/div>":i.type==240&&(t+="<div class='box'><h2><span>"+i.title+"<\/span><\/h2><div class='box-text'><img src="+i.picUrl+" width='100%' height='auto'><\/img><\/div><\/div>")});r.trim()!=""&&$("#fundInfoBox").append("<div class='box'><div class='box-text'><ul>"+r+"<\/ul><\/div><\/div>");t.trim()!=""&&$("#fundInfoBox").append(t)}else i.elementList.length<=0?errorRemark("该产品暂无投资信息，请联系管理员！"):errorRemark("该产品暂无投资信息，请联系管理员！")}})}function goToFund(){var t=getUrlParameter("fundId"),n=getUrlParameter("orally"),r=getUrlParameter("period"),i=getUrlParameter("serialno"),u=getUrlParameter("channleNo");n!=null&&n=="order"?redirectUrl("/WeixinService/business/query/orderDetail.shtml?serialno="+i):n!=null&&n=="orderOther"?redirectUrl("/WeixinService/business/query/otherOrderDetail.shtml?serialno="+i+"&fundId="+t+"&channleNo="+u):redirectUrl("/WeixinService/business/query/fundInfo.shtml?fundId="+t+"&period="+r)}$(document).ready(function(){queryElement()})